/** Name of the small variant generated by `npm run images:optimize`: foo.webp -> foo-480.webp */
export const SMALL_WIDTH = 480;

export const smallVariant = (src: string): string => src.replace(/\.webp$/i, `-${SMALL_WIDTH}.webp`);

/** Returns "foo-480.webp 480w, foo.webp 900w" for generated .webp images, otherwise undefined. */
export function buildSrcSet(src: string, fullWidth: number, resolve: (path: string) => string = (p) => p): string | undefined {
  if (!/\.webp$/i.test(src) || fullWidth <= SMALL_WIDTH) return undefined;
  return `${resolve(smallVariant(src))} ${SMALL_WIDTH}w, ${resolve(src)} ${fullWidth}w`;
}
